post.css:
.input {
  font-family: monospace;
  max-width: 190px;
  outline: none;
  border: 1px solid #dadada;
  padding: 10px;
  border-radius: 5px;
  background-color: #f3f7fe;
  transition: 0.3s;
  color: #3b82f6;
}

.input::placeholder {
  color: #3b82f6;
}

.input:focus {
  border: 1px solid #3b82f6;
  box-shadow: 0 0 0 5px #3b83f65f;
}
